#include <iostream>

struct Draft {
  int pages;
  Draft(int count) : pages(count) { std::cout << "new\n"; }
  Draft(const Draft& other) : pages(other.pages) { std::cout << "copy\n"; }
  ~Draft() { std::cout << "closed " << pages << '\n'; }
};

int main() {
  Draft original{4};
  const Draft& view = original;
  {
    Draft revision = original;
    revision.pages = 7;
    std::cout << view.pages << ' ' << revision.pages << '\n';
  }
  std::cout << view.pages << '\n';
}
// view обозначает original. revision — отдельный черновик.
// revision уничтожается во внутреннем блоке, original — при выходе из main.
